#define SPDLOG_HEADER_ONLY
#include "spdlog/async.h"
#include "spdlog/sinks/basic_file_sink.h"
#include <cassert>
#include <cstdio>
#include <memory>

int main() {
    // congested queue + non-blocking policy: flush must still be accepted
    {
        auto tp = std::make_shared<spdlog::details::thread_pool>(4, 1);
        auto sink = std::make_shared<spdlog::sinks::basic_file_sink_mt>("/tmp/ho_test/a.log", true);
        auto logger = std::make_shared<spdlog::async_logger>(
            "as", sink, tp, spdlog::async_overflow_policy::overrun_oldest);
        for (int i = 0; i < 512; i++) logger->info("msg {}", i);
        logger->flush();
        for (int i = 0; i < 512; i++) logger->info("post {}", i);
    }
